import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.DYPTBNgj.js";const p=JSON.parse('{"title":"Build a Chat Bot","description":"","frontmatter":{},"headers":[],"relativePath":"guide/chat-bot.md","filePath":"guide/chat-bot.md"}'),n={name:"guide/chat-bot.md"};function r(h,e,i,l,d,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="build-a-chat-bot" tabindex="-1">Build a Chat Bot <a class="header-anchor" href="#build-a-chat-bot" aria-label="Permalink to &quot;Build a Chat Bot&quot;">​</a></h1><p>A chat bot in Aerini is three nodes: a <strong>Webhook</strong> that receives each message, an <strong>AI Prompt</strong> that answers it, and an <strong>Output</strong> that hands the answer back to the <a href="./chat-panel">Chat Panel</a>. This page builds one, either from the starter template or by hand, and lists what to check when the reply isn&#39;t what you expect.</p><p>If you haven&#39;t read <a href="./../getting-started/concepts">Concepts</a>, do that first for what a node and a run are. Model setup for a local server such as Ollama is in <a href="./local-models">Local Models</a>, and a hosted model needs a key from <a href="./credentials">Credentials</a>; neither is repeated here.</p><h2 id="the-quick-way-the-template" tabindex="-1">The quick way: the template <a class="header-anchor" href="#the-quick-way-the-template" aria-label="Permalink to &quot;The quick way: the template&quot;">​</a></h2><p>On an empty canvas, click <strong>Chat bot template</strong>. Aerini adds a new workflow named &quot;Chat bot&quot; (with a number added if that name is taken) with the three nodes already wired and filled in. Then:</p><ol><li>Double-click <strong>AI Prompt</strong> and choose a provider and model.</li><li>Click <strong>Chat</strong> in the toolbar, then <strong>Start</strong>.</li><li>Type a message.</li></ol><h2 id="by-hand" tabindex="-1">By hand <a class="header-anchor" href="#by-hand" aria-label="Permalink to &quot;By hand&quot;">​</a></h2><ol><li><strong>Add a Webhook node.</strong> Leave its defaults, or set Path to <code>/chat</code>. Chat sends every message to this node.</li><li><strong>Add an AI Prompt node and wire the Webhook&#39;s Triggered port to its In port.</strong> If the Prompt field is empty, Aerini fills it with <code>{{Webhook.output.body.message}}</code> and says so. That expression is the text you typed in Chat, using whatever name your Webhook node has. Change it if your workflow needs something else, such as a fixed instruction followed by the message.</li><li><strong>Pick a provider and model on the AI Prompt node.</strong> A local server also needs its Base URL; see <a href="./local-models">Local Models</a>.</li><li><strong>Add an Output node and wire the AI Prompt&#39;s Success port to its In port.</strong> If the Output&#39;s Field is empty, Aerini sets it to <code>content</code>, the part of the AI Prompt&#39;s result that holds the reply text. Chat needs an Output node to show anything.</li><li><strong>Click Chat, then Start, and send a message.</strong></li></ol><p>Wire only the ports named above. A Webhook&#39;s <strong>Error</strong> port fires only when the Webhook itself fails, and AI Prompt&#39;s <strong>Files</strong> input expects a list of files, so wiring one to the other does nothing useful. To give the model the files you attach in Chat, see <a href="./chat-panel#attachments">Attachments</a>.</p><h2 id="what-chat-checks-for-you" tabindex="-1">What Chat checks for you <a class="header-anchor" href="#what-chat-checks-for-you" aria-label="Permalink to &quot;What Chat checks for you&quot;">​</a></h2><p>The banner above the messages in the Chat Panel flags these problems and fixes each with one click. <strong>Ctrl+Z</strong> on the canvas undoes a fix.</p><table tabindex="0"><thead><tr><th>Banner says</th><th>Why</th><th>Fix button</th></tr></thead><tbody><tr><td><code>&quot;AI Prompt&quot; has no prompt, so it never sees what you type here.</code></td><td>An empty Prompt (or Goal, on an AI Agent) means the model receives nothing from Chat.</td><td><strong>Use chat message</strong></td></tr><tr><td><code>Replies will show as raw JSON, because &quot;Output&quot; displays everything &quot;AI Prompt&quot; returns.</code></td><td>The Output&#39;s Field is empty, so Chat shows everything the AI node returned (<code>content</code>, token counts, model name) instead of just the reply.</td><td><strong>Show reply text only</strong></td></tr></tbody></table><p>The banner also reports wiring problems and unread attachments; see <a href="./chat-panel">Chat Panel</a>.</p><h2 id="when-it-doesn-t-work" tabindex="-1">When it doesn&#39;t work <a class="header-anchor" href="#when-it-doesn-t-work" aria-label="Permalink to &quot;When it doesn&#39;t work&quot;">​</a></h2><ul><li><strong>Nothing happens when you send a message.</strong> The workflow has to be running as a background job: press <strong>Start</strong> in the Chat Panel. The main <strong>Run</strong> button runs it once and can&#39;t deliver a reply.</li><li><strong>The reply is a block of JSON.</strong> Set the Output&#39;s Field to <code>content</code> (<code>result</code> for an AI Agent).</li><li><strong>The reply is empty or the run fails right away.</strong> Open the run in the <strong>History</strong> tab of the Output drawer and read its error. A missing model, a wrong Base URL and a missing API key are the usual causes.</li><li><strong>The model doesn&#39;t know what you said earlier.</strong> Each message is a separate run. Add an <strong>AI Memory</strong> node, as in <a href="https://github.com/Panchak2d/Aerini/blob/main/examples/Chatbot___AI_Memory___Widget.md" target="_blank" rel="noreferrer">Chatbot with AI Memory and Widget</a>.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./chat-panel">Chat Panel</a>, for sessions, attachments and settings</li><li><a href="./expressions">Expressions</a>, for the <code>{{ }}</code> syntax</li><li><a href="./examples">Examples</a>, for a chat bot with memory</li></ul>',17)])])}const g=t(n,[["render",r]]);export{p as __pageData,g as default};
